"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[46621],{46621:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/project-hail-mary.png\\"\\n          title=\\"프로젝트 헤일메리\\"\\n          author=\\"앤디 위어\\"\\n          publisher=\\"알에이치코리아\\"\\n          publishedDate=\\"2021-05-04\\"\\n          isbn=\\"9788925588735\\"\\n          rating=5\\n          tags=\\"sf\\"\\n        />\\n</center>\\n\\n## Review\\n너무 재미있게 읽었다. 이렇게 두꺼운 책을 이렇게 빨리 읽을 수 있구나 싶었다.  \\n<br>\\n기억을 잃은 주인공과 아무것도 모르는 독자가 동일한 선상에서 시작되어 주인공과 함께 조금씩 사태를 파악하게 되는 구성이 흥미롭고 재미있었다.  \\n<br>\\n모든 것을 과학적 사고로 생각하려는 너드스러움과 작가의 과학적 치밀함이 돋보이는 작품이 아닌가 생각된다.  \\n<br>\\n이 책을 읽은 독자들은 각자의 상상력을 동원해 자신만의 <mark>로키</mark>를 만들고 ```좋음! 좋음!``` 하는 모습을 상상했을 것이다.  \\n나만의 <mark>로키</mark>는 엄청 귀엽다!!  \\n<br>\\n2026년 개봉 목표로 영화화되고 있다. ```좋음! 좋음!```"}')}}]);